import gallery from "../data/gallery.json";

// Light WebP versions live in /public/img (generated by scripts/optimize-images.py).
// Full-quality originals live in the external bucket and are only loaded when a
// visitor opens a photo in the lightbox.
export const ORIGINALS_BASE_URL = (
  import.meta.env.VITE_ORIGINALS_BASE_URL ||
  "https://levinstein-images.s3.eu-north-1.amazonaws.com"
).replace(/\/$/, "");

const encodePath = (path) => path.split("/").map(encodeURIComponent).join("/");

// Light version of a photo, e.g. "wedding/0J3A0008.jpg" -> "/img/wedding/0J3A0008.webp"
export const getImageUrl = (path) => {
  const clean = path.replace(/^\/+/, "").replace(/^src\/assets\//, "");
  return `/img/${encodePath(clean.replace(/\.[^.]+$/, ".webp"))}`;
};

// Full-quality original of a photo, same path format as getImageUrl.
export const getOriginalUrl = (path) => {
  const clean = path.replace(/^\/+/, "").replace(/^src\/assets\//, "");
  return `${ORIGINALS_BASE_URL}/assets/${encodePath(clean)}`;
};

// All photos of a portfolio category: [{ src, original, width, height }]
export const getGalleryImages = (category) =>
  (gallery[category] || []).map(({ file, w, h }) => ({
    src: getImageUrl(`${category}/${file}`),
    original: getOriginalUrl(`${category}/${file}`),
    width: w,
    height: h,
  }));

const SITE_IMAGES = [
  "JV1A2929.jpg",
  "JV1A2930.jpg",
  "JV1A2976.jpg",
  "logoskitza.PNG",
  "images/face_about.jpg",
  ...[26, 27, 28, 29, 30, 31, 32, 33, 35, 36, 37].map(
    (n) => `images/home/IMG-20250604-WA00${n}.jpg`
  ),
];

export const imageUrls = Object.fromEntries(
  SITE_IMAGES.map((path) => [path, getImageUrl(path)])
);
